// npm run graphql: the gateway's two GraphQL schemas are written first, in
// services/gateway/schema/*.graphql; this generates what the code uses from
// them, with GraphQL Code Generator:
//   - the TypeScript types of each schema and of its resolvers, whose parents
//     are the engine's messages (src/core/models.ts), in src/core/generated;
//   - the schemas' text as a TypeScript module (src/core/generated/sdl.ts), so
//     the core builds them without reading files: in stage 8 it runs in a
//     browser, which has no file system.
// The generated files are committed. `npm run graphql -- --check` generates in
// memory and fails when anything differs from what is committed: a schema
// changed without regenerating does not pass the check.
import { existsSync } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";
import { codegen } from "@graphql-codegen/core";
import * as typescriptPlugin from "@graphql-codegen/typescript";
import * as resolversPlugin from "@graphql-codegen/typescript-resolvers";
import { buildSchema, isObjectType, isScalarType, parse, printSchema, specifiedScalarTypes } from "graphql";
import { repoRoot } from "./lib/paths.ts";

const gateway = join(repoRoot, "services", "gateway");
const out = join(gateway, "src", "core", "generated");
const say = (line: string) => console.log(`[graphql] ${line}`);

// Every object type of each schema has a model: the engine's message (or a
// small shape of the gateway's) that its resolvers receive as their parent.
const MODELS = "../models.ts";
const SCALARS = "../scalars.ts";
const mapped = (names: string[]) => Object.fromEntries(names.map((name) => [name, `${MODELS}#${name}Model`]));

const SCHEMAS = {
  internal: {
    objects: [
      "Person", "Session", "Market", "Entitlements", "PriceBreakdown", "Plan", "PriceListEntry", "ChangePage",
      "ChangeSummary", "Change", "ChangeVersion", "OfferContent", "ListPriceContent", "Audience", "ListeningRule",
      "OfferPrice", "OfferPeriod", "OfferPage", "Approval", "RequiredSignature", "Fact", "ValidationFinding",
      "ValidationReport", "Refusal", "Overview", "MarketTime", "Launch", "Incident", "SubscriberCount", "MarketRevenue",
      "Assumption", "Totals", "FinanceCondition", "Simulation", "AuditEvent", "AuditPage", "ChainHead", "ChainVerification",
    ],
    scalars: ["Money", "LocalDateTime", "DateTime", "MarketCode", "PlanCode", "Sha256"],
  },
  public: {
    objects: [
      "Market", "Entitlements", "PriceBreakdown", "Plan", "ListPrice", "MarketTime", "Offer", "Quote", "DemoListener", "Me", "Account", "Subscription",
      "StudentVerification", "Payment", "Receipt", "Confirmation", "Refusal",
    ],
    scalars: ["Money", "LocalDateTime", "DateTime", "Date", "MarketCode", "PlanCode"],
  },
} as const;

type Name = keyof typeof SCHEMAS;

const HEADER = (name: string) =>
  `// @generated by tools/graphql.ts from services/gateway/schema/${name}.graphql: do not edit.\n// npm run graphql regenerates it; npm run graphql -- --check compares.\n`;

async function generate(): Promise<Map<string, string>> {
  const files = new Map<string, string>();
  const sdl: Record<string, string> = {};
  for (const name of Object.keys(SCHEMAS) as Name[]) {
    const source = (await readFile(join(gateway, "schema", `${name}.graphql`), "utf8")).replaceAll("\r\n", "\n");
    // Fails here, with the line, when the schema does not build.
    const schema = buildSchema(source);
    const { objects, scalars } = SCHEMAS[name];
    const mappers = name === "public"
      ? Object.fromEntries(objects.map((object) => [object, `${MODELS}#Public${object}Model`]))
      : mapped([...objects]);
    // Both directions: an object type without a model would get the default
    // parent type, and a model for a type that is gone is a leftover.
    const objectTypes = Object.values(schema.getTypeMap())
      .filter((type) => isObjectType(type) && !type.name.startsWith("__") && !["Query", "Mutation"].includes(type.name))
      .map((type) => type.name);
    const unmapped = objectTypes.filter((typeName) => !(typeName in mappers));
    const stale = Object.keys(mappers).filter((typeName) => !objectTypes.includes(typeName));
    if (unmapped.length) throw new Error(`${name}.graphql: object types without a model: ${unmapped.join(", ")}`);
    if (stale.length) throw new Error(`tools/graphql.ts: models for types that ${name}.graphql does not have: ${stale.join(", ")}`);
    const declaredScalars = Object.values(schema.getTypeMap())
      .filter((type) => isScalarType(type) && !specifiedScalarTypes.some((builtIn) => builtIn.name === type.name))
      .map((type) => type.name);
    if (declaredScalars.sort().join() !== [...scalars].sort().join()) {
      throw new Error(`${name}.graphql declares the scalars ${declaredScalars.join(", ")}; tools/graphql.ts lists ${scalars.join(", ")}`);
    }
    const content = await codegen({
      filename: `${name}.ts`,
      schema: parse(printSchema(schema)),
      schemaAst: schema,
      documents: [],
      plugins: [{ typescript: {} }, { "typescript-resolvers": {} }],
      pluginMap: { typescript: typescriptPlugin, "typescript-resolvers": resolversPlugin },
      config: {
        // Node runs the gateway's TypeScript without a build: only erasable
        // syntax, so enums are unions of strings and imports of types say so.
        enumsAsTypes: true,
        useTypeImports: true,
        strictScalars: true,
        scalars: Object.fromEntries(scalars.map((scalar) => [scalar, `${SCALARS}#${scalar}Value`])),
        mappers,
        contextType: `../context.ts#${name === "public" ? "PublicContext" : "InternalContext"}`,
        // Every field has its resolver, written against the parent's model:
        // a field left to the default resolver is a field nobody checked.
        avoidOptionals: { resolvers: true, query: true, mutation: true },
        immutableTypes: true,
        useIndexSignature: false,
        resolverTypeWrapperSignature: "Promise<T> | T",
      },
    });
    files.set(join(out, `${name}.ts`), `${HEADER(name)}${content.replaceAll("\r\n", "\n")}`);
    sdl[name] = source;
  }
  files.set(join(out, "sdl.ts"), `${HEADER("{internal,public}")}\nexport const internalSdl: string = ${JSON.stringify(sdl["internal"])};\n\nexport const publicSdl: string = ${JSON.stringify(sdl["public"])};\n`);
  return files;
}

const files = await generate();
if (process.argv.includes("--check")) {
  const differing: string[] = [];
  for (const [path, content] of files) {
    const kept = existsSync(path) ? (await readFile(path, "utf8")).replaceAll("\r\n", "\n") : null;
    if (kept !== content) differing.push(relative(repoRoot, path).replaceAll("\\", "/"));
  }
  if (files.size === 0) throw new Error("nothing was generated");
  if (differing.length) {
    say(`generated code differs from the schemas: ${differing.join(", ")}; run npm run graphql`);
    process.exitCode = 1;
  } else {
    say(`generated code matches the schemas (${files.size} files)`);
  }
} else {
  await mkdir(out, { recursive: true });
  for (const [path, content] of files) await writeFile(path, content);
  say(`generated ${[...files.keys()].map((path) => relative(repoRoot, path).replaceAll("\\", "/")).join(", ")}`);
}
